<?php

use CRM_Civicase_Helper_CaseCategory as CaseCategoryHelper;

/**
 * Class CRM_Civicase_Page_CaseAngular.
 *
 * Define an Angular base-page for CiviCase.
 */
class CRM_Civicase_Page_CaseAngular extends \CRM_Core_Page {

  /**
   * Run Function.
   *
   * This function takes care of all the things common to all
   * pages. This typically involves assigning the appropriate
   * smarty variable :)
   *
   * @return string
   *   The content generated by running this page
   */
  public function run() {
    if (!$this->canAccessCaseCategoryFromUrl()) {
      CRM_Utils_System::permissionDenied();
      return NULL;
    }

    $loader = Civi::service('angularjs.loader');
    $loader->setPageName('civicrm/case/a');
    $loader->addModules(['crmApp', 'civicase', 'civicase-features']);
    \Civi::resources()->addSetting([
      'crmApp' => [
        'defaultRoute' => '/case/list',
      ],
    ]);
    return parent::run();
  }

  /**
   * Checks the user can access the case category in the URL.
   *
   * The page shows the "Cases" category when the URL has none. Checked here,
   * on every request, because core caches the Angular module declarations
   * (ang/civicase.ang.php) for every user and URL.
   *
   * @return bool
   *   TRUE when the user has "basic <category> information".
   */
  private function canAccessCaseCategoryFromUrl(): bool {
    $caseCategoryId = CRM_Utils_Request::retrieve('case_type_category', 'Int')
      ?: CaseCategoryHelper::getOptionValue();

    return CaseCategoryHelper::isCaseTypeCategoryAccessible((int) $caseCategoryId);
  }

  /**
   * Get Template File Name.
   *
   * @inheritdoc
   */
  public function getTemplateFileName() {
    return 'Civi/Angular/Page/Main.tpl';
  }

}
